package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    uuid.UUID `json:"id"`
	Name  string    `json:"name"`
	Email string    `json:"email"`
}

var (
	users = make(map[uuid.UUID]User)
	mutex sync.RWMutex
)

// CreateUser creates a new user and adds it to the system
func CreateUser(name, email string) (User, error) {
	mutex.Lock()
	defer mutex.Unlock()

	id, err := uuid.NewRandom()
	if err != nil {
		return User{}, fmt.Errorf("failed to generate UUID: %w", err)
	}

	user := User{
		ID:    id,
		Name:  name,
		Email: email,
	}
	users[user.ID] = user
	return user, nil
}

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()

	var userList []User
	for _, u := range users {
		userList = append(userList, u)
	}
	return userList
}

// GetUserByID returns a user by their ID
func GetUserByID(id uuid.UUID) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	user, ok := users[id]
	return user, ok
}

package api

import (
	"encoding/json"
	"fmt"
	"net/http"

	"github.com/google/uuid"
	"rep-1/internal/service"
)

// HandleUsers handles requests for /users endpoint (GET and POST)
func HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		users := service.GetAllUsers()
		json.NewEncoder(w).Encode(users)

	case http.MethodPost:
		var reqUser struct {
			Name  string `json:"name"`
			Email string `json:"email"`
		}
		if err := json.NewDecoder(r.Body).Decode(&reqUser); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}

		user, err := service.CreateUser(reqUser.Name, reqUser.Email)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(user)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID handles requests for /users/{id} endpoint (GET)
func HandleUserByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Path[len("/users/"):]

	id, err := uuid.Parse(idStr)
	if err != nil {
		http.Error(w, "Invalid user ID", http.StatusBadRequest)
		return
	}

	user, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"
	"rep-1/internal/api"
)

func main() {
	http.HandleFunc("/users", api.HandleUsers)
	http.HandleFunc("/users/", api.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"

	"github.com/google/uuid"
)

func TestCreateUser(t *testing.T) {
	// Clear users map before each test to ensure isolation
	users = make(map[uuid.UUID]User)

	name := "Test User"
	email := "test@example.com"

	user, err := CreateUser(name, email)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	if user.Name != name {
		t.Errorf("Expected user name %s, got %s", name, user.Name)
	}
	if user.Email != email {
		t.Errorf("Expected user email %s, got %s", email, user.Email)
	}
	if user.ID == uuid.Nil {
		t.Errorf("Expected user ID to be non-nil, got %v", user.ID)
	}

	retrievedUser, ok := GetUserByID(user.ID)
	if !ok {
		t.Errorf("Expected user with ID %v to be found", user.ID)
	}
	if retrievedUser.Name != name {
		t.Errorf("Expected retrieved user name %s, got %s", name, retrievedUser.Name)
	}
}

func TestGetAllUsers(t *testing.T) {
	// Clear users map before each test
	users = make(map[uuid.UUID]User)

	user1, _ := CreateUser("User One", "one@example.com")
	user2, _ := CreateUser("User Two", "two@example.com")

	allUsers := GetAllUsers()

	if len(allUsers) != 2 {
		t.Errorf("Expected 2 users, got %d", len(allUsers))
	}

	found1 := false
	found2 := false
	for _, u := range allUsers {
		if u.ID == user1.ID {
			found1 = true
		}
		if u.ID == user2.ID {
			found2 = true
		}
	}

	if !found1 || !found2 {
		t.Errorf("Expected to find both users in the list")
	}
}

func TestGetUserByID(t *testing.T) {
	// Clear users map before each test
	users = make(map[uuid.UUID]User)

	user, _ := CreateUser("Find Me", "findme@example.com")

	// Test case: user found
	retrievedUser, ok := GetUserByID(user.ID)
	if !ok {
		t.Errorf("Expected to find user with ID %v", user.ID)
	}
	if retrievedUser.Name != "Find Me" {
		t.Errorf("Expected user name 'Find Me', got %s", retrievedUser.Name)
	}

	// Test case: user not found
	nonExistentID := uuid.New()
	_, ok = GetUserByID(nonExistentID)
	if ok {
		t.Errorf("Expected not to find user with ID %v", nonExistentID)
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"rep-1/internal/service"
	"testing"

	"github.com/google/uuid"
)

func TestHandleUsers_Get(t *testing.T) {
	// Clear users map and add some test data for isolation
	service.ClearUsers()
	service.CreateUser("Alice", "alice@example.com")
	service.CreateUser("Bob", "bob@example.com")

	req, _ := http.NewRequest(http.MethodGet, "/users", nil)
	rr := httptest.NewRecorder()

	HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}

	// Check if the names are present (order might vary)
	foundAlice := false
	foundBob := false
	for _, u := range users {
		if u.Name == "Alice" {
			foundAlice = true
		}
		if u.Name == "Bob" {
			foundBob = true
		}
	}

	if !foundAlice || !foundBob {
		t.Errorf("Expected to find Alice and Bob in the response")
	}
}

func TestHandleUsers_Post(t *testing.T) {
	// Clear users map before test
	service.ClearUsers()

	userPayload := []byte(`{"name": "Charlie", "email": "charlie@example.com"}`)
	req, _ := http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(userPayload))
	req.Header.Set("Content-Type", "application/json")

	rr := httptest.NewRecorder()

	HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusCreated)
	}

	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if createdUser.Name != "Charlie" || createdUser.Email != "charlie@example.com" {
		t.Errorf("Expected created user to be Charlie, got %+v", createdUser)
	}
	if createdUser.ID == uuid.Nil {
		t.Errorf("Expected user ID to be non-nil")
	}

	// Verify user is actually in the service storage
	_, ok := service.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("Expected user with ID %v to be found in service", createdUser.ID)
	}
}

func TestHandleUserByID_Get(t *testing.T) {
	// Clear users map and add a test user
	service.ClearUsers()
	user, _ := service.CreateUser("David", "david@example.com")

	req, _ := http.NewRequest(http.MethodGet, "/users/"+user.ID.String(), nil)
	rr := httptest.NewRecorder()

	HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var retrievedUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&retrievedUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if retrievedUser.ID != user.ID || retrievedUser.Name != user.Name {
		t.Errorf("Expected user %v, got %v", user, retrievedUser)
	}

	// Test case: User not found
	nonExistentID := uuid.New()
	reqNotFound, _ := http.NewRequest(http.MethodGet, "/users/"+nonExistentID.String(), nil)
	rrNotFound := httptest.NewRecorder()
	HandleUserByID(rrNotFound, reqNotFound)

	if status := rrNotFound.Code; status != http.StatusNotFound {
		t.Errorf("handler for non-existent user returned wrong status code: got %v want %v", status, http.StatusNotFound)
	}

	// Test case: Invalid UUID
	reqInvalidID, _ := http.NewRequest(http.MethodGet, "/users/invalid-uuid", nil)
	rrInvalidID := httptest.NewRecorder()
	HandleUserByID(rrInvalidID, reqInvalidID)

	if status := rrInvalidID.Code; status != http.StatusBadRequest {
		t.Errorf("handler for invalid UUID returned wrong status code: got %v want %v", status, http.StatusBadRequest)
	}
}

